  "update.afterBackupOrphans":
    "يحتفظ Docker بالصورة التي كانت الحاوية تعمل عليها سابقًا، بلا وسم الآن، ويعرضها Unraid كصورة يتيمة. هذا هو الأثر الطبيعي لتحديث ناجح، لا علامة على تحديث فاشل، وهو تحديدًا ما يحتاجه الرجوع السريع إلى الصورة السابقة. وعند عدم الرغبة في الاحتفاظ بها، فإن المفتاح «إزالة الصورة القديمة بعد التحديث» ضمن الإعدادات، الجدول الزمني، التحديثات بعد النسخ الاحتياطي يحذف الصورة المُستبدَلة مباشرة بعد التحديث.",
