  "offsite.prune.info": "هذه الخطوة تعرض ما يحدث فقط، وهي لا تضبط أي شيء. ما إذا كانت هذه النسخة تُقلَّم يحدده append-only في الخطوة 4 وقيم الاحتفاظ في الإعدادات، الوجهات. لتقليم نسخة append-only رغم ذلك، يُشغَّل restic forget --prune على الوجهة نفسها، إما وفق جدول خاص بها أو بتشغيل خادم REST ثانٍ غير append-only لفترة قصيرة، ثم التقليم من خلاله وإيقافه مجدداً.",
