  "mcp.allowStartHint": "مع تفعيل هذا، يستطيع المساعد بدء نسخ عنصر واحد أو قسم كامل أو النسخ الاحتياطي الشامل، وإلغاء ما بدأه: {n} على الأكثر في الساعة، وبفارق {minutes} دقيقة للعنصر نفسه، و{perDay} للعنصر الواحد يوميًا. النسخ الاحتياطي يوقف الحاويات العاملة حتى ينتهي. وبدونه يستطيع المفتاح القراءة فقط.",
