  "mcp.limitReached": "zero=يوجد بالفعل {n} مفتاح نشط. يجب إبطال أحدها قبل إنشاء مفتاح آخر.|one=يوجد بالفعل مفتاح نشط واحد. يجب إبطاله قبل إنشاء مفتاح آخر.|two=يوجد بالفعل مفتاحان نشطان. يجب إبطال أحدهما قبل إنشاء مفتاح آخر.|few=توجد بالفعل {n} مفاتيح نشطة. يجب إبطال أحدها قبل إنشاء مفتاح آخر.|many=يوجد بالفعل {n} مفتاحًا نشطًا. يجب إبطال أحدها قبل إنشاء مفتاح آخر.|other=يوجد بالفعل {n} مفتاح نشط. يجب إبطال أحدها قبل إنشاء مفتاح آخر.",
  "mcp.newKeyTitle": "المفتاح الجديد",
