  "mcp.noMatch": "لا يوجد عميل مطابق. أي عميل آخر يتصل عبر «عميل آخر».",
  "mcp.connectHint": "اختيار العميل يعطي إعدادًا مصممًا له: مفتاح يحمل اسمه، والإعدادات المطلوب نسخها، وخطوة الشهادة التي يحتاجها. أي عميل آخر يتصل عبر عميل آخر. ما يقرؤه المساعد، مثل أسماء العناصر والسجل ورسائل الخطأ، يذهب إلى مزود الذكاء الاصطناعي الذي يقف خلفه، بعد أن يزيل BombVault مسارات المضيف ومواقع المستودعات وبيانات الاعتماد.",
  "mcp.groupLocal": "على هذا الحاسوب",
  "mcp.groupCloud": "في السحابة",
  "mcp.cloudWarningTitle": "يجب أن يكون BombVault متاحا من الإنترنت",
  "mcp.cloudWarning": "تستدعي هذه الخدمات BombVault من خوادم مزودها، لا من الحاسوب المحلي. عندها يجب أن يكون BombVault متاحا من الإنترنت بشهادة موثوقة علنا، خلف وكيل عكسي مثلا. يمكن لتسجيل دخول على ذلك الوكيل أن يحمي واجهة الويب، لكن يجب أن يمر ‎/mcp إلى BombVault الذي يتحقق من المفتاح بنفسه، لأن هذه الخدمات لا تستطيع تسجيل الدخول إلى وكيل. يرفض Le Chat الشهادات الموقعة ذاتيا.",
