  "mcp.setupOther": "يعمل أي عميل يتحدث Streamable HTTP. يُدخل هذا حيث يطلب خادم MCP بعيدا، مع المفتاح في أحد الترويستين.",
  "mcp.setupWhere": "مكان الملف",
  "mcp.setupNeedsNode": "يحتاج إلى Node.js، لأن mcp-remote يربط {app} بـ BombVault.",
  "mcp.keyFileLine": "يُحفظ المفتاح في ملف نصي بالسطر X-API-Key: <key> ويوضع مسار ذلك الملف في الإعدادات. يحتفظ {app} بالمسار فقط، فلا يظهر المفتاح هناك ولا في قائمة العمليات.",
  "mcp.keyFileJsonTip": "في ملف JSON هذا، تُكتب المسارات بشرطات مائلة للأمام، مثل C:/Users/sam/bombvault-key.txt، لأن الشرطة المائلة العكسية المفردة ليست JSON صالحا. يجب أن يخلو مسار ملف المفتاح من المسافات: على Windows يمرر {app} المسار الذي فيه مسافة إلى npx على جزأين.",
  "mcp.keyEnv": "يقرأ {app} المفتاح من متغير البيئة {var}.",
  "mcp.keyEnvTip": "يُضبط مرة واحدة متغير بيئة للمستخدم: في Windows ضمن الإعدادات، النظام، حول، إعدادات النظام المتقدمة، متغيرات البيئة؛ وفي macOS وLinux في ملف تعريف الصدفة. ثم يُعاد تشغيل {app}. كتابته بـ setx أو export في موجه الأوامر تترك المفتاح في سجل الصدفة. التطبيق الذي يبدأ من Dock أو Finder على macOS لا يقرأ ملف تعريف الصدفة: يوضع المفتاح وحده في ملف مثل ‎~/.bombvault-key‎، ثم يُشغَّل ‎launchctl setenv {var} \"$(cat ~/.bombvault-key)\"‎ في Terminal ويُعاد فتح {app}، ويتكرر ذلك بعد كل إعادة تشغيل للـ Mac.",
  "mcp.keyEnvUnsure": "إذا أرسل {app} اسم المتغير بدل المفتاح، فيُكتب المفتاح في الملف مكانه، ويبقى ذلك الملف خاصًا.",
  "mcp.keyPrompt": "يطلب {app} المفتاح في أول مرة يشغّل فيها الخادم ويحفظه في مخزن الأسرار الخاص به، فلا يحتوي الملف على أي مفتاح.",
  "mcp.keyDotenv": "يقرأ {app} المفتاح من السطر {var}=<key> في {file}. يجب أن يبقى ذلك الملف خاصًا.",
  "mcp.keyInFile": "لا يستطيع {app} قراءة المفتاح من أي مكان آخر، لذا يبقى نصا عاديا في هذا الملف. يجب أن يبقى الملف خاصًا، بعيدا عن المجلدات المشتركة وعن التحكم بالإصدارات.",
  "mcp.keyInApp": "يحفظ {app} المفتاح في إعداداته الخاصة، غير مشفّر بحسب ما تقوله وثائقه. يستطيع أي شخص يفتح تلك الإعدادات قراءته.",
  "mcp.keyCredential": "يحفظ {app} المفتاح مشفّرا بين بيانات الاعتماد الخاصة به: يُنشأ به بيان اعتماد من نوع Bearer Auth ويُختار في العقدة. سير العمل يذكر اسم بيان الاعتماد فقط.",
  "mcp.keyVendor": "يحفظ {app} المفتاح على خوادم مزوده ويرسله مع كل استدعاء.",
  "mcp.keyOther": "إن كان العميل يستطيع قراءة المفتاح من متغير بيئة أو من طلب سر أو من سلسلة مفاتيح النظام، فذلك أفضل من كتابة المفتاح في إعداداته.",
  "mcp.certPlaceholder": "يستخدم BombVault شهادته الخاصة. توجّه الإعدادات Node.js إليها: يُنزَّل الملف ويوضع مساره مكان العنصر النائب للشهادة.",
  "mcp.certEnv": "يستخدم BombVault شهادته الخاصة. إذا رفضها {app}، فيُضبط متغير البيئة {var} على مسار الملف المُنزَّل ويُعاد تشغيل {app}.",
  "mcp.certEnvTip": "يُضبط حيث تُضبط متغيرات بيئة المستخدم: في Windows ضمن الإعدادات، النظام، حول، إعدادات النظام المتقدمة، متغيرات البيئة؛ وفي macOS وLinux في ملف تعريف الصدفة؛ وفي الحاوية ضمن إعداداتها مع تركيب الملف داخلها. تُنزَّل الشهادة من جديد كلما أصدر BombVault شهادة جديدة. التطبيق الذي يبدأ من Dock أو Finder على macOS لا يقرأ ملف تعريف الصدفة: من أجله يُشغَّل ‎launchctl setenv {var}‎ مع مسار الملف في Terminal ثم يُعاد فتح التطبيق، ويتكرر ذلك بعد كل إعادة تشغيل للـ Mac.",
  "mcp.certSystem": "يستخدم BombVault شهادته الخاصة. إذا رفضها {app}، فيُضاف الملف المُنزَّل إلى الشهادات الموثوقة في النظام ويُعاد تشغيل {app}.",
  "mcp.certSystemTip": "في Windows، يُغيَّر اسم الملف إلى bombvault-cert.crt، ثم يُفتح ويُختار تثبيت الشهادة، المستخدم الحالي، وضع كل الشهادات في المخزن التالي، مراجع الشهادات الجذر الموثوق بها. أو يُشغَّل certutil -user -addstore Root مع مسار الملف. في macOS، يُضاف إلى سلسلة مفاتيح تسجيل الدخول في الوصول إلى سلسلة المفاتيح ويُضبط على الوثوق دائما. في Linux، يُنسخ بالامتداد .crt إلى ‎/usr/local/share/ca-certificates ويُشغَّل update-ca-certificates.",
  "mcp.certOwnList": "يستخدم BombVault شهادته الخاصة، ويتحقق {app} من الشهادات بقائمة خاصة به لا تقبل الإضافة. إذا رفض شهادة BombVault، فيلزم الوصول إلى BombVault عبر وكيل عكسي بشهادة موثوقة علنا.",
  "mcp.certOther": "يستخدم BombVault شهادته الخاصة. يُوجَّه العميل إلى الملف المُنزَّل، أو يُضاف الملف إلى الشهادات الموثوقة في النظام.",
  "mcp.certOtherTip": "العميل الذي يعمل على Node.js يأخذ الملف من NODE_EXTRA_CA_CERTS. ومعظم العملاء الآخرين يستخدمون الشهادات التي يثق بها النظام. لا يجوز إيقاف فحص الشهادات أبدا.",
  "mcp.waitTitle": "بانتظار الاستدعاء الأول",
