  "mcp.waitLineOther": "بانتظار أن يستدعي العميل BombVault",
  "mcp.waitHint": "يُعاد تشغيل {app} ليحمّل الخادم الجديد، ثم يستخدم BombVault مرة واحدة. يصبح هذا أخضر مع الاستدعاء الأول.",
  "mcp.waitHintOther": "ربط العميل. يصبح هذا أخضر مع الاستدعاء الأول.",
