  "oauth.reads": "سيتمكن من قراءة حالة النسخ الاحتياطية: ما المحمي، ومتى نُسخ كل عنصر آخر مرة، وكيف سارت عمليات التشغيل، وماذا تقول سجلاتها. تبقى الاستعادة والحذف والإعدادات في واجهة الويب هذه.",
  "oauth.unverified": "لا يعرف BombVault هذا العميل، والاسم أعلاه اختاره بنفسه. لا يُسمح به إلا إذا بدأ تسجيل الدخول هذا من هنا قبل لحظات.",
  "oauth.startedHere": "لا يُسمح به إلا إذا بدأ تسجيل الدخول هذا من هنا قبل لحظات. رابط أرسله شخص آخر قد يربط حسابه في {name} بـ BombVault هذا.",
  "oauth.loopback": "يعود هذا العميل إلى برنامج على هذا الحاسوب نفسه، ويمكن لأي برنامج هناك أن ينتحل صفته. لا يُسمح به إلا إذا بدأ تسجيل الدخول هذا من هنا قبل لحظات.",
  "oauth.allowStartHint": "عند تفعيل هذا يستطيع العميل أيضًا بدء النسخ الاحتياطي وإلغاء ما بدأه، بالحدود نفسها المطبقة على المفتاح. يوقف النسخ الاحتياطي الحاويات العاملة حتى ينتهي. يمكن تغيير ذلك لاحقًا في مربعه ضمن الإعدادات، التكاملات، خادم MCP.",
