  "anomaly.settings.title": "الحالات الشاذة",
  "anomaly.settings.hint": "يقارن كل نسخة احتياطية لعنصر بسجله الخاص ويبلّغ عمّا لا يتوافق معه. يعمل في الخلفية بعد كل نسخة احتياطية ولا يبطئ أيًّا منها. تبدأ معظم الفحوص بعد 10 نسخ احتياطية للعنصر؛ أما الإخفاقات وإعادة كتابة معظم البيانات والمصدر شبه الفارغ فتُفحص منذ البداية. تُراقَب المساحة الحرة للمستودعات المحلية ولمستودعات rclone التي تُبلغ عنها؛ وعلى مشاركة المستخدم في Unraid هي المساحة الحرة للمصفوفة كلها.",
