  "storage.flow.title": "الوجهات لكل قسم",
  "storage.flow.hint": "الإعداد الافتراضي لكل قسم. كل خط في الرسم هو مفتاح: انقر على خط أو نقطة لتشغيله أو إيقافه. الخطوط المتقطعة متوقفة. وتحت «المفاتيح» يُضبط الشيء نفسه بالأزرار. المفتاح يحدد أين تذهب النسخ الاحتياطية الجديدة. العناصر التي تتبع الإعداد الافتراضي تنتقل معه فورًا، فتذهب نسختها التالية إلى الوجهات الجديدة. النسخ الاحتياطية المخزَّنة بالفعل تبقى حيث هي، ويمكنك مع ذلك استعادتها من هناك. أما العناصر التي اختارت وجهاتها الخاصة في صفحتها فتحتفظ بها. والقواعد الخاصة بقسم ما، مثل الاحتفاظ أو الضغط أو عنوان خاص، تُضبط في صفحة الوجهة.",
